 function openInvoiceDetails(id,opener){
  const sale=window.novaSales?.list().find(x=>x.id===id&&x.source!=='DEMO');
  if(!sale||document.getElementById('novaInvoiceDetails'))return;
  const returned=window.novaSales.returnedQty(id);
  const canReturn=sale.lines.some((line,i)=>line.qty>(returned[i]||0))&&!window.novaSales.isCancelled(id);
  const ov=document.createElement('div');ov.id='novaInvoiceDetails';ov.className='nova-invoice-detail-overlay';ov.dir=tr('rtl','ltr');
  const amounts=(line,i)=>tr('المُباع ','Sold ')+line.qty+' · '+tr('المرتجع ','Returned ')+(returned[i]||0)+' · '+tr('المتاح للإرجاع ','Can return ')+Math.max(0,line.qty-(returned[i]||0));
  ov.innerHTML='<section class="nova-invoice-detail" role="dialog" aria-modal="true" aria-labelledby="novaInvoiceTitle"><header><h2 id="novaInvoiceTitle">'+tr('فاتورة ','Invoice ')+'<bdi>'+esc(sale.number)+'</bdi></h2><button type="button" class="nova-dlg-x" data-dlg-close aria-label="'+tr('إغلاق','Close')+'">×</button></header>'
   +'<div class="nova-invoice-detail-body"><div class="nova-invoice-summary"><strong dir="auto">'+esc(sale.customer||tr('عميل نقدي','Walk-in Customer'))+'</strong><bdi>'+money(sale.total)+'</bdi></div><p class="nova-muted"><bdi>'+esc(window.NovaFmt.formatDateTime(sale.at))+'</bdi> · '+payLbl(sale.payment)+'</p>'
   +'<ul>'+sale.lines.map((line,i)=>'<li><strong dir="auto">'+esc(line.name)+'</strong><small>'+amounts(line,i)+'</small></li>').join('')+'</ul>'+retHistory(id,sale.lines)+'</div>'
   +'<footer><button type="button" class="btn btn-primary nova-return-btn" data-detail-return'+(canReturn?'':' disabled')+'>'+tr('عمل مرتجع','Start return')+'</button><button type="button" class="btn btn-secondary nova-return-btn" data-detail-print>'+tr('إعادة الطباعة','Reprint')+'</button>'
   +(canReturn?'<details><summary>'+tr('المزيد','More')+'</summary><button type="button" class="btn btn-secondary nova-return-btn" data-detail-cancel>'+tr('إلغاء الفاتورة','Cancel invoice')+'</button></details>':'')+'</footer></section>';
  document.body.appendChild(ov);
  const release=dlgA11y(ov);
  const close=()=>{document.removeEventListener('keydown',key,true);release();opener?.focus()};
  const key=e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close()}};
  document.addEventListener('keydown',key,true);
  const closeButton=ov.querySelector('[data-dlg-close]');
  closeButton.onclick=close;
  ov.onclick=e=>{if(e.target===ov)close()};
  ov.querySelector('[data-detail-print]').onclick=()=>{close();window.novaReceipt?.reopenSale(id,{copy:true})};
  ov.querySelector('[data-detail-return]').onclick=()=>{close();openInvoiceReturn(id,opener,'return')};
  const cancel=ov.querySelector('[data-detail-cancel]');
  if(cancel)cancel.onclick=()=>{close();openInvoiceReturn(id,opener,'cancel')};
  closeButton.focus();
 }
